    }
}

function Init-CmdletProcess
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $CmdletRequestIdGeneratedInBegin,
        [Parameter(Mandatory)]
        $UseBatching,
        [Parameter(Mandatory)]
