#region Constant Functions

function Get-CurrentConnectionContext
{
    if ($ConnectionContextObjectId -ne $null)
    {
        return [Microsoft.Exchange.Management.ExoPowershellSnapin.ConnectionContextFactory]::GetCurrentConnectionContext($ConnectionContextObjectId)
    }

    return $null;
}

# This function tries to get the SortableDateTimePattern from the Get-Culture command. If Get-Culture returns null, static value of SortableDateTimePattern is used
function Get-SortableDateTimePattern
{
    $CultureInfo = Get-Culture
    if ($CultureInfo -ne $null)
    {
        $CultureDateTimeFormat = $CultureInfo.DateTimeFormat
        if ($CultureDateTimeFormat -ne $null)
        {
            $SortableCultureDateTimeFormat = $CultureDateTimeFormat.SortableDateTimePattern
            if ($SortableCultureDateTimeFormat -ne $null)
            {
                return $SortableCultureDateTimeFormat
            }
        }

    }
    return "yyyy'-'MM'-'dd'T'HH':'mm':'ss"
}

enum Column
{
    CmdletName
    CmdletParameters
    StartTime
    EndTime
    GenericInfo
    GenericError
}

function Log-Column
{
    param(
        [Parameter(Mandatory)]
        [Column]
        $ColumnName,

        [Parameter(Mandatory)]
        [string]
        $CmdletId,

        [Parameter(Mandatory)]
        $Value
    )

    $ConnectionContext = Get-CurrentConnectionContext
    if ($ConnectionContext -eq $null)
    {
        return;
    }

    $Logger = $ConnectionContext.Logger
    if ($Logger -eq $null)
    {
        return;
    }

    switch ($ColumnName)
    {
        ([Column]::StartTime)
        {   
            if (-not ($Value -is [DateTime]))
            {
                throw 'StartTime must be a DateTime value'
            }

            $Logger.LogStartTime($CmdletId, $Value);
            Break;
        }
        ([Column]::EndTime)
        {
            if (-not ($Value -is [DateTime]))
            {
                throw 'EndTime must be a DateTime value'
            }

            $Logger.LogEndTime($CmdletId, $Value);
            Break;
        }
        ([Column]::CmdletName)
        {
            if (-not ($Value -is [string]))
            {
                throw 'CmdletName must be a string value'
            }

            $Logger.LogCmdletName($CmdletId, $Value);               
            Break;
        }
        ([Column]::CmdletParameters)
        {
            if (-not (($Value -is [string]) -or ($Value -is [System.Collections.Generic.Dictionary`2[System.String,System.Object]])))
            {
                throw 'CmdletParameters must be a string or dictionary value'
            }

            $Logger.LogCmdletParameters($CmdletId, $Value);             
            Break;
        }
        ([Column]::GenericInfo)
        {
            if (-not ($Value -is [string]))
            {
                throw 'GenericInfo must be a string value'
            }

            $Logger.LogGenericInfo($CmdletId, $Value);               
            Break;
        }
        ([Column]::GenericError)
        {
            if (-not (($Value -is [string]) -or ($Value -is [System.Management.Automation.ErrorRecord])))
            {
                if ($Value -ne $null -and $Value.ToString() -ne $null)
                {
                    $Value = $Value.ToString();
                }
                else
                {
                    throw 'GenericError must have ToString() or ErrorRecord value'
                }
            }

            $Logger.LogGenericError($CmdletId, $Value);               
            Break;
        }
        Default {
            throw 'Invalid ColumnName'
        }
    }

}

function Init-Log
{
    param(
        [Parameter(Mandatory)]
        [string]
        $CmdletId
    )

    $ConnectionContext = Get-CurrentConnectionContext
