function Get-ErrorMessage
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $ErrorObject
    )
    process
    {

        try
        {
            # ErrorDetails or ErrorDetails.Message could be empty in some cases. 
            # For example, in case of throttling, ErrorDetails is null.
            if ($ErrorObject.ErrorDetails -eq $null -or $ErrorObject.ErrorDetails.Message -eq $null)
            {
                return $null
            }

            $errorDetailsPSObject = ConvertFrom-Json $ErrorObject.ErrorDetails.Message

            # Different types of exception can have the exception message in different objects. We have to
            # identify all different objects and add here
            # details[0].message: ManagementObjectNotFound/DirectInvokeCmdletExecutionException
            # innererror.internalexception.message: ParameterTransformationException/ODataServiceException
            if ($errorDetailsPSObject.error -ne $null -and $errorDetailsPSObject.error.details -ne $null -and $errorDetailsPSObject.error.details.length -gt 0)
            {
                return $errorDetailsPSObject.error.details[0].message
            }
            elseif ($errorDetailsPSObject.error -ne $null -and $errorDetailsPSObject.error.innererror -ne $null -and $errorDetailsPSObject.error.innererror.internalexception -ne $null)
            {
                return $errorDetailsPSObject.error.innererror.internalexception.message
            }
        }
        catch
        {
            Write-Debug('Error while parsing error object')
        }

        return $null

    }
}

function Get-ErrorId
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $ErrorObject
    )
    process
    {
        $errorId = @()
        if ($ErrorObject -ne $null -and $ErrorObject.Exception -ne $null -and $ErrorObject.Exception.Response -ne $null -and $ErrorObject.Exception.Response.Headers -ne $null)
        {
            $responseHeaders = $ErrorObject.Exception.Response.Headers
            if ($responseHeaders['X-CalculatedBETarget'] -ne $null)
            {
                $serverName = $responseHeaders['X-CalculatedBETarget']
                if ($serverName.IndexOf('.') -ge 0)
                {
                    $serverName = $serverName.Substring(0,$serverName.IndexOf('.'))
                }
                $errorId += ('Server=' + $serverName)
            }
            if ($responseHeaders['request-id'] -ne $null)
            {
                $errorId += ('RequestId=' + $responseHeaders['request-id'])
            }
            if ($responseHeaders['Date'] -ne $null)
            {
                $errorId += ('TimeStamp=' + $responseHeaders['Date'])
            }
        }

        $errorId = '[' + $($errorId -join ',') + ']'
        return $errorId
    }
}

function Get-ErrorCategoryInfo
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $ErrorObject
    )
    process
    {
        $errorCategoryInfo = [PSCustomObject]@{
            Activity = $CmdletName
            Category = [Management.Automation.ErrorCategory]::NotSpecified
            Reason = 'Exception'
            TargetName = $null
            TargetType = $null
        }

        if ($ErrorObject -ne $null -and $ErrorObject.ErrorDetails -ne $null -and $ErrorObject.ErrorDetails.Message -ne $null)
        {
            $errorDetailsPSObject = ConvertFrom-Json $ErrorObject.ErrorDetails.Message
            if ($errorDetailsPSObject.error -ne $null -and $errorDetailsPSObject.error.details -ne $null -and $errorDetailsPSObject.error.details.length -gt 0)
            {
                if (![string]::IsNullOrEmpty($errorDetailsPSObject.error.details[0].target))
                {
                    $errorCategoryInfo.TargetName = $errorDetailsPSObject.error.details[0].target
                }

                $errorCategory = $errorDetailsPSObject.error.details[0].code
                if (($errorCategory -as [int]) -ne $null)
                {
                    $errorCategory = $errorCategory -as [int]
                }
           
                
                if ($errorCategory -ne $null -and [Enum]::IsDefined([Management.Automation.ErrorCategory], $errorCategory))
                {
                    $errorCategoryInfo.Category = [Management.Automation.ErrorCategory]$errorCategory
                }
            }
        }

        if ($ErrorObject -ne $null -and $ErrorObject.Exception -ne $null -and $ErrorObject.Exception.Response -ne $null -and $ErrorObject.Exception.Response.Headers -ne $null)
        {
            $responseHeaders = $ErrorObject.Exception.Response.Headers
            if($UseBatching)
            {
                $errorCategoryInfo.Activity = $responseHeaders['Cmdlet-Name']
            }

            if ($responseHeaders['x-ExceptionType'] -ne $null)
            {
                $errorCategoryInfo.Reason = $responseHeaders['x-ExceptionType']
            }

            if ($responseHeaders['x-ExceptionTargetType'] -ne $null)
            {
                $errorCategoryInfo.TargetType = $responseHeaders['x-ExceptionTargetType']
            }
        }
        
        return $errorCategoryInfo
    }
}

# This function is used to format the error message object.
# In case of a cmdlet exception, we get a serialized Exception object from the server and we need to deserialize it and format it in the presentable manner.
# In other cases, we just return the error message as it is.
function Get-ExceptionObject
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $ErrorMessageObject
    )
    process
    {
        try
        {
            $formattedErrorMessage = "{0}|{1}|{2}"
            $errorMessagePSObject = ConvertFrom-Json $ErrorMessageObject
            if ($errorMessagePSObject -ne $null)
            {
                $errorId = ''
                if ($errorMessagePSObject.localizedString -ne $null -and $errorMessagePSObject.localizedString.stringId -ne $null)
                {
                    $errorId = $errorMessagePSObject.localizedString.stringId
                }

                $formattedErrorMessage = $formattedErrorMessage -f $errorId, $errorMessagePSObject.ClassName, $errorMessagePSObject.Message
            }
            $customException = New-Object Exception $formattedErrorMessage
            $customException.data.Add("RemoteException", $errorMessagePSObject)
        }
        catch
        {
            $customException = New-Object Exception $ErrorMessageObject   
        }

        return $customException
    }
}

function Write-ErrorMessage
{
    [CmdletBinding()]
