        {
            if ($ErrorObject.ErrorDetails -ne $null -and $ErrorObject.ErrorDetails.Message -ne $null){
                $errorStatusCode = $ErrorObject.Exception.Response.StatusCode.value__
                # Throttling case, when the status code is 429
