function Commit-CmdletLogOnError
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $CmdletRequestId,
        [Parameter(Mandatory)]
        $ErrorRecord
    )
    process{
        $endTime = Get-Date
        Log-Column -ColumnName GenericError -CmdletId $CmdletRequestId -Value $ErrorRecord
        Log-Column -ColumnName EndTime -CmdletId $CmdletRequestId -Value $endTime
        Commit-Log -CmdletId $CmdletRequestId
    }
}

function Execute-CmdletEndBlock
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $BatchBodyObj,
        [Parameter(Mandatory)]
        $CmdletRequestId,
        [Parameter(Mandatory)]
        $CmdletIDList
    )
    process{
        try
        {
            if($BatchBodyObj['requests'].Count -gt 0) 
            {
                $BatchResponse = Execute-BatchRequest -CmdletRequestId $CmdletRequestId
                Deserialize-BatchRequest -BatchResponse $BatchResponse -CmdletRequestId $CmdletRequestId
                # Resetting the batched requests as they are already handled
                $BatchBodyObj['requests'] = New-Object System.Collections.ArrayList;
                $BatchRequestParameters = New-Object System.Collections.ArrayList;
            }
    
        }
        catch
        {
            Commit-CmdletLogOnError -CmdletRequestId $CmdletRequestId -ErrorRecord $_
            throw $_
        }

        $endTime = Get-Date;
        Log-Column -ColumnName EndTime -CmdletId $CmdletRequestId -Value $endTime
        foreach ($id in $cmdletIDList)
        {
            Commit-Log -CmdletId $id
        }
    }  
}

function Execute-CmdletBatchingBeginBody
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $EnableBatchingStatus,
        [Parameter(Mandatory)]
        $ExpectingInput
    )
    process{

        $UseBatching = $false;

        # Use batching only if pipelined cmdleted being executed
        if($EnableBatchingStatus){
            # Use batching only if pipelined cmdleted being executed
            if ($ExpectingInput)
            {
                $UseBatching = $true;
            }
        }

        $BatchBodyObj = @{};
        $BatchBodyObj['requests'] = New-Object System.Collections.ArrayList;
        $BatchRequestParameters = New-Object System.Collections.ArrayList;
        return $UseBatching, $BatchBodyObj, $BatchRequestParameters;
    }
}

function Log-EndTimeInCmdletProcessBlock
{
    param(
        [boolean]
        $UseBatching,

        [string]
        $CmdletRequestId
    )
    
    # For pipeline cases, EndProcessing is not called for each cmdlet in the pipeline, so we will log the end time here.
    # When batching is enabled, and the batch request is executed in this ProcessRecord, the log will be committed either inside Execute-Command or in the end block.
    if (-not $UseBatching)
    {
        $endTime = Get-Date;
        Log-Column -ColumnName EndTime -CmdletId $CmdletRequestId -Value $endTime
    }
}

