function Retry-SingleBatchedRequest
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $FailedRequest,
        [Parameter(Mandatory)]
        $ErrorObject,
        [string]
        $CmdletRequestId
    )
    process
    {
        $Body = ConvertTo-Json $FailedRequest['body'] -Depth 10 -Compress
        $Body = ([System.Text.Encoding]::UTF8.GetBytes($Body));
        $Headers = $FailedRequest['headers']
        $Uri = $FailedRequest['url']
        $isRetryHappening = $true
        $isQuerySuccessful = $false
        $claims = Get-ClaimsFromExceptionDetails -ErrorObject $ErrorObject
        $isRetryHappening = CheckRetryAndHandleWaitTime -retryCount 0 -ErrorObject $ErrorObject -CmdletRequestId $CmdletRequestId
        for ($retryCount = 1; $retryCount -le $script:DefaultMaxRetryTimes -and $isRetryHappening; $retryCount++)
        {

                    if ($ConnectionContextObjectId -ne $null)
                    {
                        $ConnectionContext = [Microsoft.Exchange.Management.ExoPowershellSnapin.ConnectionContextFactory]::GetCurrentConnectionContext($ConnectionContextObjectId);
                        $AuthInfo = $ConnectionContext.GetAuthHeader($claims, $cmdletRequestId);
                        $claims = [string]::Empty
                    }
                    else
                    {
                        # ConnectionContextObjectId is not present, so request is from an older version of client. Hence use AuthHeaderUtils.
                        $AuthInfo = Get-AuthInfoUsingTokenProvider $TokenProviderObjectId
                    }

            $Headers['Authorization'] = $AuthInfo.AuthorizationHeader
            try
            {
                $existingProgressPreference = $global:ProgressPreference
                $global:ProgressPreference = 'SilentlyContinue'

                $timeout = Get-HttpTimeout $Headers
                $Result = Invoke-WebRequest -UseBasicParsing -TimeoutSec $timeout -Method 'POST' -Headers $Headers -Body $Body -Uri $Uri 
                $global:ProgressPreference = $existingProgressPreference
                # Print the Result
                if ($Result -ne $null -and $Result.Content -ne $null)
                {
                    $ResultObject = (ConvertFrom-JSON $Result.Content)

                    $RequestID = [int]$ResultObject.id
                    $CurrentRequestParameters = $BatchRequestParameters[$RequestID]

                    $resultSize = Get-ResultSize $CurrentRequestParameters
                    if ($resultSize -ne "Unlimited" -and $resultSize -gt 0)
                    {
                        $nextPageSize = [Math]::min($resultSize, $script:DefaultPageSize)
                    }

                    # Print the Result
                    PrintResultAndCheckForNextPage -ResultObject $ResultObject -VerifyNextPageLinkCheckRequired $true -anotherPagedQuery ([ref]$anotherPagedQuery) -resultSize $resultSize -nextPageSize $nextPageSize

                    if ($anotherPagedQuery)
                    {
                        $PagedRequest = $BatchBodyObj['requests'][$RequestID]
                        Execute-BatchedNextPageRequest -PagedRequest $PagedRequest -PagedResponse $ResultObject -ResultSize $resultSize -NextPageSize $nextPageSize -CmdletRequestId $CmdletRequestId
                    }

                }
                $isQuerySuccessful = $true
                $isRetryHappening = $false
            }
            catch
            {
                $global:ProgressPreference = $existingProgressPreference
                $claims = Get-ClaimsFromExceptionDetails -ErrorObject $_
                $isRetryHappening = CheckRetryAndHandleWaitTime -retryCount $retryCount -ErrorObject $_ -CmdletRequestId $CmdletRequestId
            }
        }

        if ($isQuerySuccessful -eq $false)
        {
            $global:EXO_LastExecutionStatus = $false;
        }
    }
}

function Deserialize-BatchRequest
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $BatchResponse,

        [string]
        $CmdletRequestId
    )
    process
    {
        # Variables used to handle next paged requests
        $resultSize = $script:DefaultPageSize
        $nextPageSize = $script:DefaultPageSize
        $anotherPagedQuery = $true

        if ($BatchResponse -eq $null -or $BatchResponse.Content -eq $null)
        {
            return 
        }

        $BatchBody = ConvertTo-Json $BatchBodyObj -Depth 10
        $BatchBodyPSObject = ConvertFrom-Json -InputObject $BatchBody
        $batchBodyIterator = 0

        $BatchedResultObject = (ConvertFrom-JSON $BatchResponse.Content)
        ForEach ($Result in $BatchedResultObject.responses)
        {
            $Result.headers | Add-Member -MemberType NoteProperty -Name 'Cmdlet-Name' -Value $BatchBodyPSObject.requests[$batchBodyIterator++].body.CmdletInput.CmdletName

            if ($Result.status -eq 200)
            {
                $ResultObject = $Result.body
                $RequestID = [int]$Result.id
                $CurrentRequestParameters = $BatchRequestParameters[$RequestID]

                $resultSize = Get-ResultSize $CurrentRequestParameters
                if ($resultSize -ne "Unlimited" -and $resultSize -gt 0)
                {
                    $nextPageSize = [Math]::min($resultSize, $script:DefaultPageSize)
                }
                # Print Result
                PrintResultAndCheckForNextPage -ResultObject $ResultObject -VerifyNextPageLinkCheckRequired $true -anotherPagedQuery ([ref]$anotherPagedQuery) -resultSize $resultSize -nextPageSize $nextPageSize

                if ($anotherPagedQuery)
                {
                    $PagedRequest = $BatchBodyObj['requests'][$RequestID]
                    Execute-BatchedNextPageRequest -PagedRequest $PagedRequest -PagedResponse $ResultObject -ResultSize $resultSize -NextPageSize $nextPageSize -CmdletRequestId $CmdletRequestId
                }
            }
            else
            {
                #Retry individual request
                $RequestID = [int]$Result.id
                $FailedRequest = $BatchBodyObj['requests'][$RequestID]
                $CustomException = Create-CustomError $Result $BatchResponse.Headers
                Retry-SingleBatchedRequest -FailedRequest $FailedRequest -ErrorObject $CustomException -CmdletRequestId $CmdletRequestId
            }
        }
    }
}

# Create custom error to convert ErrorResult into Invoke-WebRequest error format
function Create-CustomError
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [AllowNull()]
        $ErrorResult,
        [Parameter(Mandatory)]
        [AllowNull()]
        $BatchedResponseHeaders	
    )
    process
    {
        $CustomError = New-Object PSObject
        $Exception = New-Object PSObject
        $Response = New-Object PSObject
        $ErrorDetails = New-Object PSObject
		if ($ErrorResult -eq $null)
		{
			$JsonErrorMessage = '{"error":  {"details":  [{"message":  "Response is Null."}]}}'
        }
		else 
		{
			$JsonErrorMessage = $ErrorResult.body | ConvertTo-Json -Depth 10
		}

        if ($ErrorResult.body -ne $null -and $ErrorResult.body.error -ne $null -and  $ErrorResult.body.error.code -ne $null)
        {
            $Response | Add-Member -MemberType NoteProperty -Name 'StatusCode' -Value $ErrorResult.body.error.code
        }
        
        if ($BatchedResponseHeaders -ne $null)
        {
            $Response | Add-Member -MemberType NoteProperty -Name 'Headers' -Value $BatchedResponseHeaders
        }
		
		if ($ErrorResult.headers -ne $null -and $ErrorResult.headers.psobject -ne $null -and $Response.Headers -ne $null)
        {

            # In case of new versions of PS7, the response headers values are of type String[] instead of String
            $isValueArray = $false;
            if ($Response.Headers.Values.Count -ge 1)
            {
                $isValueArray = $($Response.Headers.Values)[0].GetType().IsArray
            }
            
            if ($isValueArray -eq $true)
            {
                foreach ($property in $ErrorResult.headers.psobject.properties)
                {
                    [string[]]$propertyValueArray = @($property.Value);
                    $Response.Headers[$property.Name] = $propertyValueArray;
                }
            }
            else
            {
                $ErrorResult.headers.psobject.properties | Foreach { $Response.Headers[$_.Name] = $_.Value }
            }
        }

        $ErrorDetails | Add-Member -MemberType NoteProperty -Name 'Message' -Value $JsonErrorMessage
        $Exception | Add-Member -MemberType NoteProperty -Name 'Response' -Value $Response
        $CustomError | Add-Member -MemberType NoteProperty -Name 'Exception' -Value $Exception
        $CustomError | Add-Member -MemberType NoteProperty -Name 'ErrorDetails' -Value $ErrorDetails
        $CustomError | Add-Member scriptMethod ToString { $this.ErrorDetails.Message } -Force

        return $CustomError
    }
}




