                $Headers['X-AnchorMailbox'] = 'UPN:' + $AuthInfo.UserPrincipalName
            }
        }
        # Set Client Metrics for cmdlets
        if ($ConnectionContextObjectId -ne $null)
        {
            $Headers['connection-id'] = $ConnectionContext.ConnectionId;
        }
        # Response Format 
        $Headers['X-ResponseFormat'] = 'clixml'
        # Serialization Level 
        $Headers['X-SerializationLevel'] = 'Partial'

        # We are using PSUICulture to choose locale over PSCulture because PSCulture is used to format 
        # dates, numbers, currencies etc. Whereas, PSUICulture is responsible for loading appropriate translatable 
        # resources for the application
        if ($PSUICulture -ne $null)
        {
            $Headers['Accept-Language'] = $PSUICulture
        }
        # Accepting gzip encoding
        $Headers['Accept-Encoding'] = 'gzip'
        
        # Capture the client module version info in the header.
        $Headers['X-ClientModuleVersion'] = Get-ModuleVersion

        #Set Client Application in Headers
        $Headers['X-ClientApplication'] = 'ExoManagementModule'
        # Stamp X-ConnectionWorkload header when set by a specialized Connect-* cmdlet.
        if ($ConnectionContext -ne $null -and ![string]::IsNullOrWhiteSpace($ConnectionContext.ConnectionWorkload))
        {
            $Headers['X-ConnectionWorkload'] = $ConnectionContext.ConnectionWorkload
        }
    }
}

# This function return Http timeout for Invoke-WebRequest.
# It checkes cmdlet inside $CmdletHttpTimeoutCollection, if found then return that value otherwise DefaultHTTPTimeout.
function Get-HttpTimeout
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Parameters
    )
    process
    {

        $cmdletName = $Parameters['X-CmdletName']
        if (![string]::IsNullOrEmpty($cmdletName) -and $CmdletHttpTimeoutCollection -ne $null -and $CmdletHttpTimeoutCollection.ContainsKey($cmdletName))
        {
            #1 minute more than server timeout so we don't timeout before the server.
            return $CmdletHttpTimeoutCollection[$cmdletName] + 60;
        }
        
        return $script:DefaultHTTPTimeout;
    }
}

# This function does Validation of ResultSize and returns -1 if invalid and parse the String.
# It also handles Special scenarios like Unlimited in the ResultSize Parameter.
function Get-ResultSize
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Parameters
    )
    process
    {
        $resultSize = $script:DefaultPageSize
        if ($Parameters.ContainsKey('ResultSize'))
        {
            if ($Parameters['ResultSize'] -ne 'Unlimited')
            {
                $resultSize = [int]::Parse($Parameters['ResultSize'])
                if ($resultSize -le 0)
                {
                    Write-Error('ResultSize must be greater than 0')
                    return -1
                }
            }
            else
            {
                $resultSize = 'Unlimited'
            }
        }
        return $resultSize
    }
}

# This function prints the Result after the cmdlet executed successfully
# It additionally checks if the another Page needs to be fetched.
# This function is called at 4 places in the script, out of 3 are batching cases.
# In cases of batching, we want to print confirmation message as well, which is why
# we have passed isFromBatchingRequest = true by default. Non-batching case will pass this as false.
function PrintResultAndCheckForNextPage
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $ResultObject,

        [bool]
        $verifyNextPageLinkCheckRequired,

        [ref]$anotherPagedQuery,

        [AllowNull()]
        $resultSize,

        [AllowNull()]
        $nextPageSize,

        [boolean]
        $isFromBatchingRequest=$true
    )
    process
    {
        
        $deserializedResult = [System.Management.Automation.PSSerializer]::Deserialize($ResultObject.value[0]._cliXml)

        $deserializedResult

        if ($verifyNextPageLinkCheckRequired -eq $true)
        {
            $anotherPagedQuery.Value = Check-NextPageLinkExists -ResultObject $ResultObject -deserializedResult $deserializedResult -resultSize $resultSize -nextPageSize $nextPageSize
        }

        # Print any warning message if returned in the response
        $warnings = $ResultObject.'@adminapi.warnings';
        if ($warnings -ne $null)
        {
            foreach ($warning in $warnings)
            {
                # Decode FilterWarningsInPagination string only once to increase efficiency
                if($FilterWarningsInPaginationDecoded -eq '')
                {
                    $FilterWarningsInPaginationDecoded = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($FilterWarningsInPagination))
                }

                # Filter out warnings occured due to pagination, except in batching where no pagination happens hence print all warnings.
                if(!$anotherPagedQuery.Value -or !$FilterWarningsInPaginationDecoded.Contains($warning))
                {
                    Write-Warning $warning
                }
            }
        }
        # Print any handled Exceptions if returned in the response
        
        $errorsCaptured = $ResultObject.'@adminapi.errors';
        if ($errorsCaptured -ne $null)
        {
            foreach ($exc in $errorsCaptured)
            {
                $global:EXO_LastExecutionStatus = $false;
                Write-Error $exc
            }
        }

        # In batching cases, we need to print WhatIf message separately. -Confirm parameter cases never do batching
        if ($isFromBatchingRequest)
        {
            $confirmationMessage = $ResultObject.'@adminapi.confirmationmessage';
            if ($confirmationMessage -ne $null)
            {
                $confirmationMessage = 'What if: ' + $confirmationMessage
                Write-Host $confirmationMessage
            }
        }
    }
}

function Check-NextPageLinkExists
{
    [CmdletBinding()]
    param(
        $ResultObject,

        $deserializedResult,
       
        [AllowNull()]
        $resultSize,

        [AllowNull()]
        $nextPageSize
    )
    process
    {    

        # Check if another page request is to be triggered
        if ($resultSize -ne 'Unlimited')
        {
            $receivedSize = $deserializedResult.count
            if ($receivedSize -eq $nextPageSize -and $resultSize -gt $nextPageSize -and $ResultObject.'@odata.nextLink' -ne $null)
            {
                return $true
            }
        }
        elseif($ResultObject.'@odata.nextLink' -ne $null)
        {
            return $true
        }

        return $false
    }
}

function CheckRetryAndHandleWaitTime
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $retryCount,
        
        [Parameter(Mandatory)]
        $ErrorObject,

        [string]
        $CmdletRequestId,

        $IsFromBatchingRequest=$true
    )
    process
    {

        if ($global:Error -ne $null -and $global:Error.Count -gt 0 -and $global:Error[0].CategoryInfo -ne $null -and $global:Error[0].CategoryInfo.Activity -eq 'Invoke-WebRequest')
        {
            $global:Error.RemoveAt(0)   
        }
        Write-Verbose('Query {0} failed.' -f ($retryCount + 1))
        if ($retryCount -eq $script:DefaultMaxRetryTimes)
        {
            Log-Column -ColumnName GenericError -CmdletId $CmdletRequestId -Value 'Maximum error count reached:'
            Log-Column -ColumnName GenericError -CmdletId $CmdletRequestId -Value $ErrorObject
            Write-Error('Maximum retry count reached.')
            Write-ErrorMessage $ErrorObject
            return $false
        }

        $waitTime = Get-WaitTimeForRetry $ErrorObject $retryCount

        #If the Get-WaitTimeForRetry function returns -1, this means that the exception will not be retried
        if ($waitTime -ge 0)
        {
            $isRetryHappening = $true
            Write-Verbose('Sleeping for {0} milliseconds' -f $waitTime)
            Start-Sleep -Milliseconds $waitTime
            $waitTime = 0
        }
        else
        {
            Log-Column -ColumnName GenericError -CmdletId $CmdletRequestId -Value $ErrorObject
            Write-ErrorMessage $ErrorObject
            return $false
        }

        return $isRetryHappening;
    }
}

function Transform-Parameters
{
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        $Parameters,

        [Parameter(Mandatory)]
        $cmdletClass
        )
    process
    {
        $params = @{}
        
        foreach ($boundParam in $Parameters.GetEnumerator())
        {
            # This null check handles the cases when a PSCredential type object is passed as null
            if ($boundParam.Value -eq $null)
            {
                $params[$boundParam.Key] = $null;
                continue;
            }
            if ($boundParam.Value -is [switch])
            {
                $params[$boundParam.Key] = $($true -eq $boundParam.Value);
            }
            elseif ($boundParam.Value -is [HashTable])
            {
                 $params[$boundParam.Key] = ConvertTo-HashTable $boundParam.Value;
            }
            elseif ($PowerShellParameters.Contains($boundParam.Key))
            {
                $params[$boundParam.Key] = $boundParam.Value.ToString()
            }
            elseif ($boundParam.Value -is [HashTable[]])
            {
                $params[$boundParam.Key + '@odata.type'] = '#Collection(Exchange.GenericHashTable)';
                $params[$boundParam.Key] = $boundParam.Value;
            }
            elseif (($cmdletClass.Parameters[$boundParam.Key].ParameterType.Name -eq 'PSObject') -or ($cmdletClass.Parameters[$boundParam.Key].ParameterType.Name -eq 'PSCustomObject'))
            {
                $params[$boundParam.Key] = $boundParam.Value
            }
            elseif (($boundParam.Value.GetType() -eq [PSObject]) -or ($boundParam.Value.GetType() -eq [System.Management.Automation.PSCustomObject]))
            {
                # Output from previous cmdlet in the pipe.
                # If ValueFromPipeline or ValueFromPipelineByPropertyName is specified in the boundParam, then extract only the Property and send
                # to the API. This will ensure same behavior as Powershell Pipeline.
                if(($cmdletClass.Parameters[$boundParam.Key].Attributes.ValueFromPipelineByPropertyName -eq $true -or
                    $cmdletClass.Parameters[$boundParam.Key].Attributes.ValueFromPipeline -eq $true) -and 
                   ($(Get-Member -InputObject $boundParam.Value -MemberType Property,NoteProperty -Name $boundParam.Key) -ne $null))
                {
                    $params[$boundParam.Key] = [string] $($boundParam.Value | select -ExpandProperty $boundParam.Key);
                }
                else
                {
                    $params[$boundParam.Key] = [string] $boundParam.Value.ToString();
                }
            }
            elseif ($boundParam.Value -is [Object[]] -and $boundParam.Value.Count -ge 1 -and (($boundParam.Value[0].GetType() -eq [PSObject]) -or ($boundParam.Value[0].GetType() -eq [System.Management.Automation.PSCustomObject])))
            {
                for ($i = 0 ; $i -lt $boundParam.Value.Count ; $i++)
                {
                    $boundParam.Value[$i] = [string] $boundParam.Value[$i].ToString();
                }
                $params[$boundParam.Key] = $boundParam.Value;
            }
            elseif ($boundParam.Value -is [Byte[]])
            {
                $params[$boundParam.Key] = ConvertTo-ByteArray $boundParam.Value;
            }
            elseif ((($boundParam.Value -is [Object[]]) -or ($boundParam.Value -is [System.Collections.ArrayList])) -and $boundParam.Value.Count -ge 1 -and $boundParam.Value[0] -is [Byte[]])
            {
                $params[$boundParam.Key + '@odata.type'] = '#Collection(Exchange.ByteArrayType)';
                $params[$boundParam.Key] = [object[]](ConvertTo-ByteArrayCollection $boundParam.Value);
            }
            elseif (($boundParam.Value -ne $null) -and ($boundParam.Value.GetType() -eq [DateTime] -or $boundParam.Value.GetType() -eq [DateTimeOffset]))
            {
                $SortableDateTimePattern = Get-SortableDateTimePattern
                $params[$boundParam.Key] = $boundParam.Value.ToUniversalTime().ToString($SortableDateTimePattern)
            }
            elseif (($boundParam.Value -ne $null) -and ($boundParam.Value.GetType() -eq [IPAddress]))
            {
                $params[$boundParam.Key] = $boundParam.Value -as [string]
            }
            elseif ($boundParam.Value -is [CultureInfo])
            {
                $params[$boundParam.Key] = $boundParam.Value -as [string]
            }
            elseif ($boundParam.Value -is [TimeSpan])
            {
                $params[$boundParam.Key] = $boundParam.Value -as [string]
            }
            elseif ($boundParam.Value.PSObject.BaseObject -is [string])
            {
                 # This check is required for the scenario when we do Get-Content to read the file content
                 # In this case, Get-Content also has the metadata, which is why ConvertTo-Json starts hanging.
                 # Therefore, we use the BaseObject value, which is a is the string value without the metadata.
                 $params[$boundParam.Key] = $boundParam.Value.PSObject.BaseObject
            }
            elseif (($boundParam.Value -is [Object[]]) -and ($boundParam.Value.PSObject.BaseObject -is [Object[]]) -and ($boundParam.Value.Count -ge 1 -and $boundParam.Value[0] -is [string]))
            {
                # Block for handling cases when some content is read using Get-content and it contains metadata as ETS (Extended Type System) properties.
                # ETS Properties: These p

